test('empty scene opens the file picker; progress disappears after success and new uploads cancel the old notice',async()=>{
 const {d,w}=await editor({guest:true}),doc=w.document,input=doc.querySelector('#vg-upload');let chosen=0,complete;input.click=()=>chosen++;doc.querySelector('#vg-composer-empty').click();assert.equal(chosen,1);assert.equal(doc.querySelector('.vg-upload-button'),null);
 const timeouts=new Map(),nativeSet=w.setTimeout.bind(w),nativeClear=w.clearTimeout.bind(w);let id=9000;w.setTimeout=(cb,ms,...args)=>ms===2500?(timeouts.set(++id,cb),id):nativeSet(cb,ms,...args);w.clearTimeout=n=>{timeouts.delete(n);nativeClear(n)};
 w.VillegramUpload={upload:async(_sb,_file,_path,progress)=>{progress?.(45);await new Promise(r=>complete=r)}};
 Object.defineProperty(input,'files',{configurable:true,value:[new w.File(['photo'],'one.jpg',{type:'image/jpeg'})]});input.dispatchEvent(new w.Event('change'));await tick();assert.equal(doc.querySelector('#vg-upload-feedback').hidden,false);assert.equal(doc.querySelector('#vg-upload-progress').hidden,false);assert.equal(doc.querySelector('#vg-upload-progress').value,45);assert.equal(doc.querySelector('#vg-upload-spinner').hidden,false);assert.equal(doc.querySelector('#vg-upload-feedback').parentNode,doc.querySelector('#vg-composer-screen'));assert.equal(doc.querySelector('#vg-composer-screen').classList.contains('is-uploading'),true);assert.equal(doc.querySelector('#vg-composer-empty').disabled,true);
 complete();await tick();assert.equal(doc.querySelector('#vg-upload-progress').hidden,true);assert.equal(doc.querySelector('#vg-upload-spinner').hidden,true);assert.equal(doc.querySelector('#vg-composer-screen').classList.contains('is-uploading'),false);assert.equal(timeouts.size,1);assert.match(doc.querySelector('#vg-upload-status').textContent,/Mídia enviada/);assert.equal(doc.querySelector('#vg-composer-empty').hidden,true);doc.querySelector('#vg-media-add').click();assert.equal(chosen,2);
 input.dispatchEvent(new w.Event('change'));await tick();assert.equal(timeouts.size,0);assert.equal(doc.querySelector('#vg-upload-progress').hidden,false);complete();await tick();assert.equal(doc.querySelectorAll('[data-select]').length,2);for(const cb of timeouts.values())cb();assert.equal(doc.querySelector('#vg-upload-feedback').hidden,true);assert.equal(doc.querySelector('#vg-upload-status').textContent,'');d.window.close();
});

