 doc.querySelector('#vg-media-options').click();doc.querySelector('#vg-media-delete').click();assert.equal(doc.querySelector('#vg-composer-visual img').style.objectFit,'contain');doc.querySelector('#vg-media-options').click();doc.querySelector('#vg-media-delete').click();assert.equal(fit.hidden,true);d.window.close();
