test('approver alert opens the pending queue without discarding a composition; approving clears the queue',async()=>{
 const post={id:uid,source:'guest_submission',status:'pending_review',title:'Momento do hóspede',caption:'Café',author_name:'Hóspede',media:[{kind:'photo',url:'assets/photo.webp'}],cover_index:0};const {d,w}=await editor({initialRows:[post]}),doc=w.document;w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'))};
 doc.querySelector('[data-photo]').click();doc.querySelector('#vg-post-form').elements.title.value='Composição em andamento';const event=new w.CustomEvent('villegram-review-open',{cancelable:true});assert.equal(doc.dispatchEvent(event),false);await tick();assert.equal(doc.querySelector('#vg-filter').value,'pending_review');assert.equal(doc.querySelectorAll('[data-review]').length,1);assert.equal(doc.querySelector('#vg-post-form').elements.title.value,'Composição em andamento');let changed=0;doc.addEventListener('villegram-review-changed',()=>changed++);doc.querySelector('[data-review]').click();doc.querySelector('[data-approve]').click();await tick();assert.equal(changed,1);assert.equal(doc.querySelectorAll('[data-review]').length,0);assert.match(doc.querySelector('#vg-library-message').textContent,/Nenhum momento/);d.window.close();
});

