 pointer(w,layer,'pointerdown',1,150,160);pointer(w,layer,'pointermove',1,60,160);pointer(w,layer,'pointerup',1,60,160);assert.match(scene.style.filter,/sepia/);assert.equal(scene.style.transform,'scale(1)');assert.equal(doc.querySelector('#vg-filter-toast').textContent,'Aconchego');
