test('new moment centers upload canvas and vertical photo movement stays scrollable',async()=>{const {d,w}=await editor(),doc=w.document;let target,options;w.HTMLElement.prototype.scrollIntoView=function(o){target=this;options=o};doc.querySelector('#vg-new').click();await new Promise(r=>setTimeout(r,30));assert.equal(target.id,'vg-composer-screen');assert.equal(options.block,'center');doc.querySelector('[data-photo]').click();const layer=doc.querySelector('#vg-scene-gesture'),scene=doc.querySelector('#vg-composer-visual img');Object.defineProperties(scene,{naturalWidth:{value:1000},naturalHeight:{value:1600}});doc.querySelector('#vg-composer-visual').getBoundingClientRect=()=>({left:0,top:0,width:200,height:320});const fire=(type,x,y)=>{const e=new w.MouseEvent(type,{bubbles:true,cancelable:true,clientX:x,clientY:y,button:0});Object.defineProperty(e,'pointerId',{value:1});layer.dispatchEvent(e);return e};assert.equal(fire('pointerdown',100,100).defaultPrevented,false);assert.equal(fire('pointermove',100,170).defaultPrevented,false);fire('pointercancel',100,170);await new Promise(r=>setTimeout(r,520));assert.equal(doc.querySelector('.vg-wheel').hidden,true);d.window.close()});

test('six photos can be scrolled to the last and reordered with cover identity preserved',async()=>{const {d,w,saved}=await editor(),doc=w.document;for(let i=0;i<6;i++)doc.querySelector('[data-photo]').click();let strip=doc.querySelector('.vg-media-strip');assert.equal(strip.querySelectorAll('[data-select]').length,6);let requested;strip.scrollBy=o=>{requested=o.left;strip.scrollLeft+=o.left};doc.querySelector('[data-strip-next]').click();assert.equal(requested,150);const last=doc.querySelector('[data-select="5"]');pointer(w,last,'pointerdown',1,160,30);pointer(w,last,'pointermove',1,60,30);assert.equal(strip.scrollLeft,250);pointer(w,last,'pointerup',1,60,30);await new Promise(r=>setTimeout(r,320));last.click();doc.querySelector('#vg-scene-extra [data-up]').click();const f=doc.querySelector('#vg-post-form');f.elements.title.value='Seis fotos';f.elements.caption.value='Ordem';f.elements.property_id.value='1';doc.querySelector('[name=draft]').click();await tick();assert.equal(saved[0].publication.media.length,6);assert.equal(saved[0].publication.cover_index,0);d.window.close()});
